WITH daily AS (SELECT substr(updated,1,10) AS date, SUM(gross) AS gross, SUM(gross+fee+funding+liquidation_fee) AS net, COUNT(*) AS n FROM positions_usdt GROUP BY substr(updated,1,10)), running AS (SELECT *, SUM(gross) OVER (ORDER BY date) AS cum_gross, SUM(net) OVER (ORDER BY date) AS cum_net FROM daily) SELECT date,cum_gross AS value,'累计毛损益' AS series,net AS day_net,n AS records FROM running UNION ALL SELECT date,cum_net AS value,'累计净损益' AS series,net AS day_net,n AS records FROM running ORDER BY date,series;
